        self.val = val
        self.left = left
        self.right = right


def tree_to_level_order(root):
    if root is None:
        return []
    result = []
    queue = [root]
    while queue:
        node = queue.pop(0)
        if node is None:
            result.append(None)
            continue
        result.append(node.val)
        queue.append(node.left)
        queue.append(node.right)
    while result and result[-1] is None:
        result.pop()
    return result


def build_tree_from_traversals(preorder, inorder):
    index_of = {val: i for i, val in enumerate(inorder)}
    pre_idx = [0]

    def build(in_left, in_right):
        if in_left > in_right:
            return None
        root_val = preorder[pre_idx[0]]
        pre_idx[0] += 1
        root = TreeNode(root_val)
        mid = index_of[root_val]
        root.left = build(in_left, mid - 1)
        root.right = build(mid + 1, in_right)
        return root

    root = build(0, len(inorder) - 1)
    return tree_to_level_order(root)

